"""Vision-led edition. One coherent destination, nine editorial chapters."""
pages.clear();metadata.clear()
EMAIL='info@mountparadisejava.com'
def chapter(img,k,title,desc,text):
 return hero(img,k,title,desc)+f'<section class="section intro" id="discover"><p class="eyebrow">The Mount Paradise vision</p><div class="split"><h2>{k}</h2><p>{text}</p></div></section>'
def story(img,k,title,text,dark=False):
 return f'<section class="section feature {"dark" if dark else ""}">{pic(img,title,"Illustrative vision / "+k)}<div class="feature-copy"><p class="eyebrow">{k}</p><h2>{title}</h2><p>{text}</p></div></section>'
def closevision(url,label):
 return '<section class="section next-chapter"><p class="eyebrow">Continue the story</p>'+link(url,label)+'</section>'
def gallery(items):
 return '<section class="section editorial-gallery">'+''.join('<article>'+pic(i,t,'Illustrative vision / '+t)+f'<h3>{t}</h3><p>{d}</p></article>' for i,t,d in items)+'</section>'
def add(file,title,desc,body):page(file,title,desc,body)
add('discover.html','Discover Mount Paradise','The vision for a mountain destination in Trawas, East Java: hospitality, private homes, remarkable gardens and a life closer to nature.',
 chapter('destination-overview','A destination taking shape','A life shaped<br><em>by the mountain.</em>','Trawas, East Java. A place to stay, gather, and live.','Mount Paradise brings exceptional stays, private residences and memorable occasions into one connected mountain landscape. Our long-term ambition extends across approximately 40–50 hectares, developed in considered chapters, with the gardens and the spaces between buildings given as much care as the buildings themselves.')
 +story('eucalyptus-drive','The private approach','The journey<br>sets the rhythm.','Rainbow eucalyptus follows the private driveway up from the main road. Layers of green, changing bark and the gradual rise into the hills introduce a quieter world.',True)
 +story('arrival-baobab','A distinctive arrival','Rooted in<br>something remarkable.','African baobab at the entrance gives Mount Paradise a memorable welcome. The landscape already has its own character, which the next chapters will preserve and enrich.')
 +story('garden-water','Mountain spring water','Water connects<br>the whole story.','Spring water arriving from the surrounding volcanic mountains is part of the identity of the land. Flowing water, natural stone and lush planting inspire the proposed baths, garden walks and everyday life here. The water story begins with its source and its relationship to this landscape.',True)
 +story('community-gardens-new','A community within a destination','Room for<br>different ways of life.','Private homes, a grand Main Lodge and country-style Arvorest Woods offer distinct experiences within a shared setting. Hospitality and residences can grow together, supported by recreation, gardens and a continuing social life.')
 +'<section class="section"><p class="eyebrow">The development journey</p>'+highlights([('Already taking root','Arvorest Woods','A partially developed country enclave with glamping, a pond, chickens and birds.'),('The next chapters','The shared destination','The Main Lodge, occasions spaces, private homes, sports facilities and Mountain Baths form the wider plan.'),('The long view','A living landscape','The eventual 40–50-hectare ambition makes room for an arboretum, botanical gardens and future neighborhoods, shaped around the terrain.')])+'</section>'+closevision('main-lodge.html','Discover the Main Lodge'))
add('main-lodge.html','The Main Lodge','The planned heart of Mount Paradise: grand lobby, restaurant, café, terraces, hotel wing and exceptional spaces to come together.',
 chapter('main-lodge','The Main Lodge','Grand in scale.<br><em>Warm at heart.</em>','A family of welcoming spaces in volcanic stone and timber.','The Main Lodge is envisioned as the social heart of Mount Paradise. Layered rooflines, garden courts and deep verandas give a substantial destination the intimacy of a lodge. A grand lobby, restaurant, café, bar and event spaces sit alongside quieter future rooms and suites.')
 +story('lodge-arrival-new','Arrival & lobby','A generous<br>first welcome.','On the arrival side, a generous landscaped forecourt and sheltered porte cochère welcome guests into the grand lobby. Hotel wings extend behind connected pavilions, with garden courts breaking down the scale and covered paths linking the whole lodge.',True)
 +story('clubhouse-restaurant','The restaurant','The pleasure<br>of a beautiful table.','A dining room for long lunches, family occasions and memorable evenings. Rich stonework, exposed timber and garden-facing windows establish the material character of the destination.')
 +story('lodge-cafe-new','Café & terraces','Morning coffee.<br>Afternoon conversation.','Broad sheltered terraces create places to sit throughout the day. The café opens into the landscape, with small tables, comfortable chairs and the feeling of being part of a larger garden.',True)
 +story('lodge-hotel-wings','The hotel vision','A quieter wing.<br>A longer stay.','The hotel vision grows directly from the Main Lodge: a collection of connected wings stepping through the gardens, with an ambition of more than 100 rooms, including generous suites. Balconies and terraces would open toward mountain outlooks on both sides of the ridge. Cabins and private lodges sit farther out across the wider destination, primarily as privately owned homes, with selected rental stays a possibility.')
 +closevision('occasions.html','Explore extraordinary occasions'))
add('occasions.html','Extraordinary occasions','A vision for corporate retreats, conferences, private weddings and celebrations in the mountains of East Java.',
 chapter('wedding-garden','Extraordinary occasions','Some moments<br><em>deserve a mountain.</em>','A destination envisioned for meaningful work and exceptional celebrations.','Mount Paradise is being designed around the whole occasion. A conference hall, smaller meeting rooms, garden ceremony settings and sheltered dining terraces make room for leadership retreats, private weddings and celebrations that unfold over more than a single day. These are illustrative settings for the future destination.')
 +story('conference-hall','Conferences & corporate retreats','A room for<br>big ideas.','A dedicated conference hall combines the practical needs of a working gathering with the warmth of the Main Lodge. Flexible seating, presentation facilities and garden-facing breakout areas are part of the design ambition.',True)
 +story('event-boardroom','Leadership & private meetings','Focused conversation.<br>A wider perspective.','A more intimate meeting room offers space for strategy sessions, board discussions and leadership offsites. Beyond the table, gardens and shared meals create room for the conversation to continue.')
 +story('wedding-reception','Private weddings','An evening<br>worth remembering.','The wedding vision moves naturally from garden vows to candlelit dinner beneath timber roofs. Sheltered spaces, beautiful planting and warm lighting create a celebration with a strong sense of place.',True)
 +story('occasion-weekend','The whole occasion','More than<br>the main event.','A welcome meal, a terrace conversation, a morning walk. Future accommodation and dining are planned alongside event spaces, so families and teams can spend meaningful time together.')
 +closevision('main-lodge.html','Explore the Main Lodge'))
add('wellness.html','Wellness & recreation','The proposed Mountain Baths, spa, indoor swimming, fitness, tennis, padel and racquetball at Mount Paradise.',
 chapter('grand-baths-new','Wellness & recreation','From the mountain.<br><em>A deeper renewal.</em>','Spring water, generous bathing rituals and space to feel restored.','At the heart of wellness is a substantial mountain bathhouse: a sequence of warm pools, cool immersions, sheltered soaking halls, spa treatments and quiet garden terraces. Water and the volcanic landscape set the tone. Alongside this sanctuary, indoor swimming, fitness and outdoor sport bring energy and balance to mountain life.')
 +story('spring-spa-ritual','Volcanic-filtered mountain spring water','A journey through stone.<br>A ritual of renewal.','The water story begins high in the surrounding mountains, where spring water makes its slow journey through ancient volcanic rock before flowing down toward the land. Basalt and andesite provide a natural filtering medium. This mountain source inspires the bathing experience: flowing water, warm stone and an unhurried ritual centered on a silky feel on the skin, freshly rinsed hair and a sense of lightness that carries beyond the bath.',True)
 +story('mountain-baths','The bathing sanctuary','More than a soak.<br>A world to unwind in.','A generous collection of bathing spaces would create a complete spa journey: warm immersion pools, cool plunges, steam rooms, indoor soaking halls and secluded resting terraces. Treatment pavilions and garden paths connect the experiences, allowing an entire afternoon to unfold at its own pace.')
 +story('indoor-pool','Indoor swimming','A swim for<br>every season.','A substantial indoor pool is envisioned beneath a timber roof, with generous daylight and woodland views. Lap swimming, quiet recovery and sheltered poolside space would complement the outdoor pool gardens.',True)
 +gallery([('tennis-garden','Tennis in the highlands','A dedicated court setting with generous run-off space, planted boundaries and a courtside place to rest.'),('padel-garden','A new social rhythm','Padel courts bring an energetic, sociable game into the recreation plan, with spectator terraces close by.'),('racquetball','The indoor racquet club','An enclosed racquetball court adds a fast-paced indoor option alongside the outdoor tennis and padel facilities.'),('indoor-fitness','Strength, movement & focus','A fully indoor gym, with cardio and strength equipment, connects exercise to the landscape through generous windows.')])
 +story('clubhouse-spa','Baths & spa','The quieter<br>half of the day.','Warm soaking pools, cool plunges, steam, treatment rooms and resting terraces form the Mountain Baths vision. Natural stone and the mountain water story give this sanctuary its own identity.',True)
 +closevision('botanical-gardens.html','Walk into the gardens'))
add('800-club.html','800 Club','A proposed private mountain club with a whiskey bar, library, cigar lounge, billiards and intimate dining at Mount Paradise.',
 chapter('club-library','The 800 Club','Good company.<br><em>Rare pleasures.</em>','A private mountain club for conversation, culture and the art of lingering.','Named for the setting above 800 meters, the 800 Club is envisioned as Mount Paradise’s intimate social address. Rich timber, leather chairs, bookshelves and attentive hospitality create a club with its own character. Its center of gravity is conversation, friendship and the pleasure of a place that feels familiar.')
 +story('club-bar','The whiskey room','A considered pour.<br>A longer conversation.','A dedicated members’ bar is envisioned around a carefully selected whiskey collection, classic cocktails and knowledgeable hosting. Small tastings and quiet evenings give the room a rhythm of its own.',True)
 +story('club-cigars','The cigar lounge','Leather, books<br>and a little privacy.','A separate, dedicated cigar lounge brings deep leather armchairs, reading lamps and a sheltered terrace into a relaxed private setting. The design intention keeps this experience distinct from the wider dining and family spaces.')
 +story('club-billiards','The club rooms','An unhurried<br>kind of competition.','Billiards, chess, a well-chosen book and the occasional spirited debate. These rooms are designed for members to enjoy familiar pursuits and discover shared interests.',True)
 +story('club-dinner','Private dining & culture','A table with<br>something to say.','Intimate dinners, guest speakers, tastings and cultural evenings could form the club calendar. Membership would offer a continuing relationship with Mount Paradise, with wider facility access defined as the destination develops.')
 +'<section class="section"><div class="split"><h2>Belonging,<br>above all.</h2><p>The 800 Club is a proposed membership concept. Its spaces, membership categories and access arrangements are still being shaped. Wellness and recreation have their own dedicated facilities; the club brings a more private social world to the mountain.</p></div></section>'+closevision('wellness.html','Explore wellness & recreation'))
add('botanical-gardens.html','Arboretum & botanical gardens','A proposed living collection of remarkable trees, fern walks, flowering gardens and water landscapes at Mount Paradise.',
 chapter('garden-arboretum','Arboretum & botanical gardens','A living collection.<br><em>A lasting landscape.</em>','A future chapter devoted to trees, water and discovery.','Building on the variety already growing across Mount Paradise, the proposed arboretum and botanical gardens would create a destination within the destination. The idea is generous and quiet: remarkable specimens, shaded paths, seasonal color and places to stop and look more closely.')
 +story('garden-ferns','The fern walk','Follow<br>the shade.','Tree ferns create a lush lower canopy around winding paths and volcanic boulders. Small watercourses and sheltered benches could make this one of the most intimate parts of the garden.',True)
 +story('garden-flowers','Seasonal color','A landscape<br>that keeps changing.','Tabebuia and jacaranda suggest moments of flowering color within the predominantly green landscape. Carefully composed groves and open lawns would give each season its own expression.')
 +story('garden-water','The water gardens','Still water.<br>Moving light.','Ponds, small cascades and quiet viewing decks would connect the garden to the mountain water story. Natural edges and lush planting keep the experience grounded in the terrain.',True)
 +story('garden-collection','The arboretum','Meet the trees.<br>Know the place.','A living collection could bring attention to the distinctive species already present across the development: cannonball trees, African tulip trees, casuarina, cypress forms and more. Botanical interpretation and thoughtful paths would turn a walk into a small discovery.')
 +'<section class="section"><p class="eyebrow">A future chapter</p><div class="split"><h2>Growing from<br>what is here.</h2><p>The garden imagery illustrates a proposed direction, rather than completed grounds. The eventual area and routes will develop with the wider plan. African baobab at the entrance and rainbow eucalyptus along the approach remain distinctive anchors in the Mount Paradise landscape.</p></div></section>'+closevision('discover.html','Return to the wider vision'))
add('arvorest-woods.html','Arvorest Woods','The country-style chapter of Mount Paradise: luxury glamping, pondside life, chickens, birds and a gentle woodland atmosphere.',
 chapter('woods-glamping','Arvorest Woods','A country rhythm.<br><em>A world of small wonders.</em>','Luxury glamping and a quieter connection to the everyday outdoors.','Arvorest Woods is a partially developed subdivision within Mount Paradise, with luxury glamping, a pond, chickens and birds. It brings an easy country character to the wider destination. The images on this page are illustrative mood studies, reserved for replacement with photography from the real grounds.')
 +story('woods-pond','Pondside life','Watch the water.<br>Lose track of time.','A pond, birdsong and a place to sit give this chapter its relaxed center. The atmosphere is informal, green and close to the everyday life of the countryside.',True)
 +story('woods-breakfast','Glamping & slow mornings','The day begins<br>outside.','Comfortable glamping and simple outdoor rituals are part of Arvorest’s character. A covered deck, a breakfast table and the sound of the trees make a different kind of mountain stay.')
 +story('woods-country','The country garden','Small things.<br>Lasting memories.','Chickens, birds and the changing garden offer everyday encounters with nature. This lived-in country spirit gives Arvorest Woods an identity of its own.',True)
 +story('woods-evening','Evenings among the trees','A little warmth.<br>A little company.','Lanterns, timber and a sheltered place to gather suggest the atmosphere for future evenings here. This visual direction will evolve with photographs and stories from the existing enclave.')
 +closevision('discover.html','Explore the wider Mount Paradise'))
# One catalogue, three clear categories, eight visual models.
rename={'fern-retreat':('Garden Cabin','cabins'),'mountain-cabin':('Mountain Cabin','cabins'),'orchard-family':('Courtyard Lodge','lodges'),'garden-lodge':('Mountain Lodge','lodges'),'forest-lodge':('Forest Lodge','lodges'),'vista-lodge':('Vista Lodge','lodges'),'ridge-reserve':('Ridge Estate','estates'),'paradise-estate':('Paradise Estate','estates')}
# Both cabins are complete one-bedroom homes, with distinct exterior characters.
for model in collection:
 if model['slug']=='mountain-cabin':
  model.update(form='Single-storey one-bedroom cabin', desc='A warm timber and volcanic-stone cabin with room to settle in. The enlarged concept brings together a cozy living area, kitchenette and small dining table, with a separate bedroom and enclosed bathroom behind. A sheltered porch keeps everyday life close to the mountain garden.', entertaining='Sheltered porch with two lounge chairs', alt='Enlarged Mountain Cabin with timber cladding, stone base, a sheltered porch and kitchen-dining space visible inside')
 elif model['slug']=='fern-retreat':
  model.update(form='Single-storey one-bedroom garden cabin', desc='A generous veranda and private lawn shape this light-filled garden home. The refreshed concept makes room for an open living area, a compact kitchen and indoor dining, with a private bedroom behind a full-height wall and an enclosed bathroom reached from an internal passage. The bedroom sits within a volcanic-stone enclosure on the left, with private garden-facing windows, while a curving path leads to broad steps and the main living entrance. Warm timber and deep eaves preserve its intimate garden character.', entertaining='Broad veranda with a lounge nook and outdoor table', alt='Garden Cabin with a broad veranda, private stone bedroom windows on the left and a central approach to the glazed living, kitchen and dining space at golden hour')
# Lodge collection: clear bedroom progression and private rear arrival.
lodge_updates={
 'garden-lodge':dict(bedrooms='2 bedrooms',form='Single-storey two-bedroom mountain home',desc='Our signature two-bedroom Mountain Lodge brings together a sheltered veranda, private pool and generous mountain outlook. Dark volcanic stone and warm timber frame relaxed living spaces, with an intimate scale for a couple, a small family or visiting friends.'),
 'orchard-family':dict(bedrooms='3 bedrooms',form='Three-bedroom home arranged around a courtyard',desc='Three bedrooms sit within connected wings around a generous courtyard lawn. A larger family pool, covered BBQ dining and space for a casual game of badminton make this a home for unhurried days together.',water='Generous private family swimming pool',garden='Courtyard lawn with a badminton net and fruit-tree borders',entertaining='Covered BBQ dining terrace and lawn games'),
 'vista-lodge':dict(bedrooms='3 bedrooms',form='Broad single-storey three-bedroom lodge',desc='A complete three-bedroom home arranged along a broad mountain-facing veranda. A long private pool follows the outlook, with a comfortable lounge and a single sheltered dining area giving the terrace a relaxed residential character.',entertaining='Sheltered dining for six, BBQ area and a veranda lounge'),
 'forest-lodge':dict(bedrooms='4 bedrooms',form='Two-storey four-bedroom forest home',desc='The most expansive lodge in the collection, with four bedrooms, an upper timber balcony and generous living spaces opening into the forest. A substantial swimming pool and a reconfigured terrace create room to swim, lounge and gather among the trees.',water='Large private swimming pool with a generous terrace',entertaining='Sheltered lounge, garden dining and poolside terrace')
}
for model in collection:
 if model['slug'] in lodge_updates:
  model.update(lodge_updates[model['slug']]);model['parking']='Private driveway and parking behind the lodge'
collection.sort(key=lambda t: ['mountain-cabin','fern-retreat','garden-lodge','orchard-family','vista-lodge','forest-lodge','ridge-reserve','paradise-estate'].index(t['slug']))
res='<section class="page-heading"><p class="eyebrow">Private residences / Ownership collection</p><h1>Your place<br><em>in the mountains.</em></h1><p>Cabins. Lodges. Estates. Eight ways to make Mount Paradise your own.</p></section><section class="section collection-intro" id="discover"><div class="split"><h2>Choose your<br>way of living.</h2><p>Explore the residence models offered for ownership, from an intimate cabin to a generous private estate. Each architectural concept shares warm timber, volcanic stone and a private relationship with the garden. Final layouts, specifications and availability are discussed individually with our sales team.</p></div><div class="catalogue-tabs" aria-label="Residence categories"><a href="#cabins">Cabins <small>2 models</small></a><a href="#lodges">Lodges <small>4 models</small></a><a href="#estates">Estates <small>2 models</small></a></div><div class="model-menu">'
for t in collection:
 name,group=rename[t['slug']]
 res+=f'<a href="#{t["slug"]}"><img src="assets/{t["image"]}.jpg" alt="{name}" loading="lazy"><strong>{name}</strong><small>{group.title()} · {t["form"]}</small></a>'
res+='</div></section>'
for group,title,desc in [('cabins','A simpler foothold.','Compact private escapes with a garden and sheltered porch.'),('lodges','Room to make it yours.','Two-, three- and four-bedroom homes with distinct settings for family life and entertaining. Every lodge is planned with its own driveway and parking behind the house.'),('estates','A more expansive world.','Generous homes and grounds for longer stays and bringing everyone together.')]:
 res+=f'<section class="section collection-group" id="{group}"><p class="eyebrow">{group}</p><h2>{title}</h2><p class="collection-lead">{desc}</p>'
 for t in collection:
  name,g=rename[t['slug']]
  if group!=g:continue
  text=t['desc'].replace('An intimate lodge','An intimate cabin').replace('Clubhouse','Main Lodge')
  res+=f'<article class="collection-lodge" id="{t["slug"]}">{pic(t["image"],name,"Residence concept / "+name)}<div class="collection-details"><div><h3>{name}</h3><p>{text}</p>'+link('mailto:sales@mountparadisejava.com?subject='+quote('Mount Paradise | '+name),'Enquire about '+name)+'</div><dl>'
  for label,key in [('Architecture','form'),('Garden','garden'),('Pool','water'),('Outdoor living','entertaining')]:res+=f'<div><dt>{label}</dt><dd>{t[key].replace("Clubhouse","Main Lodge")}</dd></div>'
  if group=='lodges':res+=f'<div><dt>Bedrooms</dt><dd>{t["bedrooms"]}</dd></div><div><dt>Arrival</dt><dd>{t["parking"]}</dd></div>'
  res+='</dl></div></article>'
 res+='</section>'
res+='<section class="section contact-band"><div><p class="eyebrow">Residence ownership</p><h2>Find your<br>mountain home.</h2><p>For model availability, specifications and ownership enquiries, speak with the sales team.</p></div><div>'+link('mailto:sales@mountparadisejava.com','sales@mountparadisejava.com')+'</div></section>'
add('residences.html','Cabins, lodges & estates','Explore eight private residence models across Cabins, Lodges and Estates at Mount Paradise. Ownership enquiries: sales@mountparadisejava.com.',res)
add('index.html','The Mount Paradise vision','An elevated way to stay, gather, and live. Discover the vision for Mount Paradise in Trawas, East Java.',
 hero('main-lodge','Mount Paradise / Trawas, East Java','An elevated way to<br><em>stay, gather, and live.</em>','A mountain destination taking shape. Exceptional hospitality, private homes and extraordinary occasions.',True)
 +'<section class="section intro" id="discover"><p class="eyebrow">The vision</p><div class="split"><h2>More than a place.<br>A way of life.</h2><p>Imagine a mountain destination where a garden walk leads to a beautiful table, a private home belongs to a wider community, and the most important moments have room to unfold. This is the vision for Mount Paradise.</p></div>'+link('discover.html','Discover the whole story')+'</section>'
 +feature('lodge-social-new','The Main Lodge','A generous heart.<br>A warm welcome.','Layered timber roofs, rich volcanic stone, dining terraces and garden rooms. The planned Main Lodge brings hospitality and social life together.','main-lodge.html','Explore the Main Lodge',True)
 +feature('lodge-cafe-new','The mountain lifestyle','Good food.<br>Time to enjoy it.','Breakfast beneath the timber eaves. A fresh lunch after a swim. An afternoon that leaves room for a walk, a book and another coffee. The pleasure of Mount Paradise is in the rhythm of the whole day.','main-lodge.html','Discover life around the lodge')
 +feature('spring-spa-ritual','Wellness & recreation','Energy for the day.<br>Space to restore.','Mountain Baths, indoor swimming, tennis, padel, racquetball and fitness. An ambitious plan for an active, restorative mountain life.','wellness.html','Explore wellness & recreation',True)
 +feature('garden-arboretum','Arboretum & botanical gardens','A landscape<br>worth getting lost in.','A proposed living collection of remarkable trees, fern walks, water gardens and seasonal color.','botanical-gardens.html','Walk into the garden vision')
 +feature('club-library','The 800 Club','A world of<br>good company.','A private members’ club envisioned around books, leather armchairs, rare whiskeys and intimate evenings.','800-club.html','Enter the 800 Club',True)
 +feature('signature-lodge','Private residences','A place<br>of your own.','A sheltered veranda, a private pool and a garden of your own. The two-bedroom Mountain Lodge captures the everyday appeal of mountain living, within a wider collection of cabins, lodges and estates.','residences.html','Explore the residence collection')
 +'<section class="section"><p class="eyebrow">Extraordinary occasions</p><h2>For the moments<br>that bring us together.</h2>'+cards([('conference-hall','Leadership & ideas','A change of perspective.','A purpose-designed conference and meeting setting for meaningful time together.','occasions.html','Explore the occasions vision'),('wedding-garden','Private celebrations','A mountain to remember.','Garden vows, candlelit dining and the possibility of a whole weekend together.','occasions.html','Imagine the occasion')])+'</section>'
 +feature('woods-glamping','Arvorest Woods','The country<br>side of paradise.','A partially developed enclave of luxury glamping, pondside life, chickens and birds. A gentler chapter within the wider destination.','arvorest-woods.html','Discover Arvorest Woods',True)
 +'<section class="section contact-band"><div><p class="eyebrow">The next chapter</p><h2>A vision<br>with room to grow.</h2><p>Explore the destination as it takes shape, or speak with us about making a home within it.</p></div><div>'+link('mailto:info@mountparadisejava.com','General enquiries')+'<br>'+link('mailto:sales@mountparadisejava.com','Residence sales')+'</div></section>')
# Consolidated pages remain redirect-only for previously shared links.
redirects={'stay.html':'main-lodge.html','gather.html':'occasions.html','corporate-retreats.html':'occasions.html','weddings.html':'occasions.html','land.html':'discover.html','vision.html':'discover.html','clubhouse.html':'main-lodge.html','lodges.html':'residences.html','lodge-tiers.html':'residences.html','garden-lodge.html':'residences.html#garden-lodge','living.html':'residences.html'}
